    $st=$pdo->prepare('SELECT outcome,result_code FROM subscriber_auth_attempts WHERE document_hash=? ORDER BY id DESC LIMIT 1');$st->execute([fs_subscriber_document_hash($document)]);$remoteAttempt=$st->fetch();subscriber_account_expect(($remoteAttempt['outcome']??'')==='blocked'&&($remoteAttempt['result_code']??'')==='REMOTE_FORBIDDEN','Bloqueio remoto não foi auditado com código operacional.');
