    $rateLimited=false;try{fs_subscriber_login_password($pdo,$document,'senha-incorreta',false,['authenticator'=>$authenticator,'fetcher'=>$fetcher]);}catch(RuntimeException $e){$rateLimited=str_contains($e->getMessage(),'15 minutos');}subscriber_account_expect($rateLimited,'Limite de tentativas da senha HubSoft não foi aplicado.');
