    $verified=fs_subscriber_login_verify($pdo,$login['challenge'],$login['_test_code'],false);subscriber_account_expect(!empty($verified['ok'])&&(int)$verified['account']['id']===$accountId,'OTP correto não autenticou a conta esperada.');
    $reuseBlocked=false;try{fs_subscriber_login_verify($pdo,$login['challenge'],$login['_test_code'],false);}catch(RuntimeException $e){$reuseBlocked=true;}subscriber_account_expect($reuseBlocked,'OTP foi reutilizado.');
