    fs_subscriber_account_anonymize($pdo,$accountId);$anonymized=fs_subscriber_account($pdo,$accountId);$st=$pdo->prepare('SELECT status,document_encrypted,verified_phone_encrypted FROM subscriber_external_links WHERE account_id=?');$st->execute([$accountId]);$link=$st->fetch();subscriber_account_expect($anonymized['status']==='anonymized'&&$anonymized['display_name']===null&&$link['status']==='revoked'&&$link['document_encrypted']===null&&$link['verified_phone_encrypted']===null,'Anonimização preservou identidade ou contato da conta.');
