    $pdo->rollBack();unset($_SESSION['subscriber_account_id'],$_SESSION['subscriber_session_version'],$_SESSION['subscriber_authenticated_at'],$_SESSION['subscriber_auth_method']);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();unset($_SESSION['subscriber_account_id'],$_SESSION['subscriber_session_version'],$_SESSION['subscriber_authenticated_at'],$_SESSION['subscriber_auth_method']);throw$e;}
echo "OK: {$checks} verificações integradas de conta, OTP e tolerância HubSoft.\n";
